const BlendLayer = BaseTileLayer.createSubclass({
  // multiplyLayers stores tile layers
  // used as the basis for creating
  // a blend layer. Layers stored in this property
  // will be blended using "multiply" operation.
  properties: {
    multiplyLayers: null,
  },
});

